// @generated by:gauntlet run:godseye-local-infrastructure
import { randomUUID } from "node:crypto";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
  allocationState,
  type InfrastructureFixture,
  infrastructureFixture,
} from "./infra-helpers.js";

describe("durable infrastructure uncertainty and protective stops", () => {
  let fixture: InfrastructureFixture;
  beforeEach(async () => {
    fixture = await infrastructureFixture();
  });
  afterEach(async () => {
    await fixture.store.close();
  });

  it.each(["network", "firewall", "data", "sandbox"] as const)(
    "T-AC-23 T16 retains reservations and never blindly recreates after a lost %s acknowledgment",
    async (action) => {
      fixture.provider.failedAcknowledgments.add(action);
      const { allocation } = await fixture.admit();
      if (!allocation.runId) throw new Error("Fixture run missing");
      await fixture.infrastructure.foundation.tick("lost-receipt-worker");
      const effects = structuredClone(fixture.provider.effects);

      await fixture.infrastructure.foundation.reconcile(
        fixture.freshOwner(),
        allocation.runId,
        randomUUID(),
      );
      await fixture.infrastructure.foundation.tick("reconcile-worker");

      expect(fixture.provider.effects).toEqual(effects);
      expect(await allocationState(fixture, allocation.id)).toMatchObject({
        state: "quarantined",
        cleanupState: "not_required",
      });
      const next = await fixture.prepare();
      await expect(
        fixture.infrastructure.admit(
          fixture.freshOwner(),
          { preparationId: next.id, expectedHash: next.hash },
          randomUUID(),
        ),
      ).rejects.toMatchObject({ status: 409 });
    },
  );

  it("T-AC-23 T17 releases an acknowledged stopped allocation only after exact provider absence without recreating anything", async () => {
    fixture.provider.inspectResult = (inspection) =>
      inspection.running ? { ...inspection, quotaEnforced: false } : inspection;
    const { allocation } = await fixture.admit();
    if (!allocation.runId) throw new Error("Fixture run missing");
    await fixture.infrastructure.foundation.tick("absent-worker");
    fixture.provider.resources.delete(allocation.id);
    const effects = structuredClone(fixture.provider.effects);

    await fixture.infrastructure.foundation.reconcile(
      fixture.freshOwner(),
      allocation.runId,
      randomUUID(),
    );

    expect(await allocationState(fixture, allocation.id)).toMatchObject({ state: "released" });
    expect(fixture.provider.effects).toEqual(effects);
    fixture.provider.failedAcknowledgments.clear();
    expect((await fixture.admit()).allocation.state).toBe("reserved");
  });

  it("T-AC-23 T18 stops only the exact owned sandbox after a lost start acknowledgment and retains data", async () => {
    fixture.provider.failedAcknowledgments.add("start");
    const { allocation } = await fixture.admit();

    await fixture.infrastructure.foundation.tick("start-uncertainty-worker");

    expect(fixture.provider.effects.map(({ action }) => action)).toEqual([
      "network",
      "firewall",
      "data",
      "sandbox",
      "start",
      "quarantine",
    ]);
    expect(fixture.provider.resources.get(allocation.id)).toMatchObject({
      running: false,
      data: { scope: { allocationId: allocation.id } },
    });
    expect(await allocationState(fixture, allocation.id)).toMatchObject({
      state: "unknown",
      cleanupState: "pending",
    });
  });

  it("T-AC-23 T18 keeps cleanup pending when the protective stop acknowledgment is lost", async () => {
    fixture.provider.failedAcknowledgments.add("start");
    fixture.provider.failedAcknowledgments.add("quarantine");
    const { allocation } = await fixture.admit();
    if (!allocation.runId) throw new Error("Fixture run missing");
    await fixture.infrastructure.foundation.tick("stop-uncertainty-worker");

    await fixture.infrastructure.foundation.reconcile(
      fixture.freshOwner(),
      allocation.runId,
      randomUUID(),
    );

    expect(await allocationState(fixture, allocation.id)).toMatchObject({
      state: "quarantined",
      cleanupState: "pending",
    });
    expect(
      fixture.provider.effects.filter(({ action }) => action === "quarantine").length,
    ).toBeGreaterThan(0);
    expect(fixture.provider.effects.filter(({ action }) => action === "start")).toHaveLength(1);
    expect(fixture.provider.resources.get(allocation.id)?.data).toBeDefined();
  });

  it("T-AC-26 T24 contains a post-start cancellation without touching another allocation", async () => {
    const other = await fixture.prepare(undefined, fixture.production.id);
    const otherAllocation = await fixture.infrastructure.admit(
      fixture.freshOwner(),
      { preparationId: other.id, expectedHash: other.hash },
      randomUUID(),
    );
    await fixture.infrastructure.foundation.tick("other-worker");
    const { allocation } = await fixture.admit();
    if (!allocation.runId) throw new Error("Fixture run missing");
    const runId = allocation.runId;
    fixture.provider.beforeAction = async (action, scope) => {
      if (
        action === "inspect" &&
        scope &&
        fixture.provider.resources.get(scope.allocationId)?.running
      )
        await fixture.infrastructure.foundation.cancel(fixture.freshOwner(), runId, randomUUID());
    };

    await fixture.infrastructure.foundation.tick("post-start-cancel-worker");

    expect(await allocationState(fixture, allocation.id)).toMatchObject({
      state: "unknown",
      cleanupState: "stopped",
    });
    expect(fixture.provider.resources.get(allocation.id)?.running).toBe(false);
    expect(fixture.provider.resources.get(otherAllocation.id)?.running).toBe(true);
    expect([
      ...new Set(
        fixture.provider.effects
          .filter(({ action }) => action === "quarantine")
          .map(({ allocationId }) => allocationId),
      ),
    ]).toEqual([allocation.id]);
  });

  it("T-AC-26 T24 stops a late start acknowledgment even after cancellation reconciliation already confirmed a stop", async () => {
    const { allocation } = await fixture.admit();
    if (!allocation.runId) throw new Error("Fixture run missing");
    let entered = () => {};
    let release = () => {};
    const starting = new Promise<void>((resolve) => {
      entered = resolve;
    });
    const paused = new Promise<void>((resolve) => {
      release = resolve;
    });
    fixture.provider.beforeAction = async (action) => {
      if (action === "start") {
        entered();
        await paused;
      }
    };
    const dispatch = fixture.infrastructure.foundation.tick("late-start-worker");
    try {
      await starting;
      await fixture.infrastructure.foundation.cancel(
        fixture.freshOwner(),
        allocation.runId,
        randomUUID(),
      );
      await fixture.infrastructure.foundation.reconcile(
        fixture.freshOwner(),
        allocation.runId,
        randomUUID(),
      );
      expect(fixture.provider.resources.get(allocation.id)?.running).toBe(false);
      expect(await allocationState(fixture, allocation.id)).toMatchObject({
        cleanupState: "pending",
      });
    } finally {
      release();
      await dispatch;
    }

    expect(fixture.provider.resources.get(allocation.id)?.running).toBe(false);
    expect(await allocationState(fixture, allocation.id)).toMatchObject({
      cleanupState: "stopped",
    });
    expect(fixture.provider.resources.get(allocation.id)?.data).toBeDefined();
  });

  it("T-AC-26 T24 retains reservations when cancellation sees absence while a network create is still in flight", async () => {
    const { allocation } = await fixture.admit();
    if (!allocation.runId) throw new Error("Fixture run missing");
    let entered = () => {};
    let release = () => {};
    const creating = new Promise<void>((resolve) => {
      entered = resolve;
    });
    const paused = new Promise<void>((resolve) => {
      release = resolve;
    });
    fixture.provider.beforeAction = async (action) => {
      if (action === "network") {
        entered();
        await paused;
      }
    };
    const dispatch = fixture.infrastructure.foundation.tick("late-network-worker");
    try {
      await creating;
      await fixture.infrastructure.foundation.cancel(
        fixture.freshOwner(),
        allocation.runId,
        randomUUID(),
      );
      await fixture.infrastructure.foundation.reconcile(
        fixture.freshOwner(),
        allocation.runId,
        randomUUID(),
      );
      expect((await allocationState(fixture, allocation.id)).state).not.toBe("released");
      const next = await fixture.prepare();
      await expect(
        fixture.infrastructure.admit(
          fixture.freshOwner(),
          { preparationId: next.id, expectedHash: next.hash },
          randomUUID(),
        ),
      ).rejects.toMatchObject({ status: 409 });
    } finally {
      release();
      await dispatch;
    }

    expect(fixture.provider.resources.get(allocation.id)?.network).toBeDefined();
    expect((await allocationState(fixture, allocation.id)).state).not.toBe("released");
    expect(fixture.provider.effects.filter(({ action }) => action === "network")).toHaveLength(1);
  });

  it("T-AC-26 T22 rejects an absence snapshot captured before a delayed network acknowledgment arrives", async () => {
    const { allocation } = await fixture.admit();
    if (!allocation.runId) throw new Error("Fixture run missing");
    let entered = () => {};
    let release = () => {};
    const creating = new Promise<void>((resolve) => {
      entered = resolve;
    });
    const paused = new Promise<void>((resolve) => {
      release = resolve;
    });
    fixture.provider.beforeAction = async (action) => {
      if (action === "network") {
        entered();
        await paused;
      }
    };
    const dispatch = fixture.infrastructure.foundation.tick("stale-absence-worker");
    try {
      await creating;
      await fixture.infrastructure.foundation.cancel(
        fixture.freshOwner(),
        allocation.runId,
        randomUUID(),
      );
      const inspect = fixture.provider.inspect.bind(fixture.provider);
      fixture.provider.inspect = async (...args) => {
        const snapshot = await inspect(...args);
        release();
        await dispatch;
        return snapshot;
      };

      await fixture.infrastructure.foundation.reconcile(
        fixture.freshOwner(),
        allocation.runId,
        randomUUID(),
      );

      expect(fixture.provider.resources.get(allocation.id)?.network).toBeDefined();
      expect((await allocationState(fixture, allocation.id)).state).not.toBe("released");
    } finally {
      release();
      await dispatch;
    }
  });
});
